// Dimensions of the voronoi cells in screen space
const vec2 dims = vec2(500,500);


// We find the `duplicated` in the multiverse of repeated screens that
// is closest to `point`
vec2 closestParallel(vec2 point, vec2 duplicated){
    return duplicated + floor((point-duplicated)/dims+0.5)*dims;
}

bool edgy(vec2 point, vec2 mid){
    vec2 normd1 = abs(mid-point+dims/2.);
    vec2 normd2 = abs(mid-point-dims/2.);
    return normd1.x<1. || normd1.y<1. || normd2.x<1. || normd2.y<1.;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord)
{
    // Radius of centerpoint of voronoi cell
    const float point_radius = 10.;
    // Array of centerpoints
    float x = mod(200.,250.);
    float y = mod(50.*iTime,x);
    vec2 p[] = vec2[](
        iResolution.xy/2.,
        iResolution.xy/2.+vec2(x,y)
    );
    // Array of colors of voronoi cells
    const vec3 cols[] = vec3[](
        vec3(255,0,0),
        vec3(0,255,0)
    );
    // The recordholder of closest voronoi centerpoint gets to
    // decide the color
    vec3 col = vec3(0,0,0);
    float minl = length(iResolution.xy);
    for (int i = 0; i < p.length(); i++) {
        float dist = distance(fragCoord, closestParallel(fragCoord,p[i]));
        if (dist < minl) {
            col = cols[i];
            minl = dist;
            // We override the color with black it it's too close
            if (dist < point_radius) {
                col = vec3(0,0,0);
            }
        }
    }
    // center torus border
    for (int i = 0; i < p.length(); i++) {
        if (edgy(fragCoord, p[i])){
            col = vec3(0,0,0);
        }
    }
    // Output to screen
    fragColor = vec4(col/255.,1.0);
}
